/**
 * BuzzKill logo lockup (shield + wordmark + tagline), 640x251 PNG, base64.
 *
 * Inlined so the PDF Lambdas can embed it at runtime — they cannot read the
 * web `apps/web/public/images/logo.png` asset, which ships only to the browser
 * bundle. Regenerate from that source with:
 *   sips -Z 640 apps/web/public/images/logo.png --out /tmp/logo.png
 *   base64 -i /tmp/logo.png | tr -d "\n"
 */
export const BUZZKILL_LOGO_W = 640;
export const BUZZKILL_LOGO_H = 251;
export const BUZZKILL_LOGO_PNG_BASE64 =
  "";
